import { nanoid } from "nanoid";
import { AuditId as makeAuditId, SessionId as makeSessionId, SnapshotId as makeSnapshotId } from "./types/branded.js";
// =============================================================================
// ID PREFIXES
// =============================================================================
/**
 * ID prefixes for different entity types
 */
export const ID_PREFIX = {
    SESSION: "sess",
    SNAPSHOT: "vreko",
    AUDIT: "audit",
    CHECKPOINT: "cp",
};
// =============================================================================
// INTERNAL HELPERS
// =============================================================================
/**
 * Generate a cryptographically random alphanumeric suffix
 * Note: This is a private helper, not exported, so no special annotation needed
 */
function randomSuffix(length = 6) {
    const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
    let result = "";
    const bytes = new Uint8Array(length);
    // Use crypto.getRandomValues for browser/Node compatibility
    crypto.getRandomValues(bytes);
    for (let i = 0; i < length; i++) {
        result += chars[bytes[i] % chars.length];
    }
    return result;
}
/**
 * Slugify a description for use in snapshot IDs
 * Converts "Before fixing auth flow" to "before-fixing-auth-flow"
 */
function slugify(description, maxLength = 30) {
    return description
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9\s-]/g, "") // Remove non-alphanumeric
        .replace(/\s+/g, "-") // Spaces to hyphens
        .replace(/-+/g, "-") // Collapse hyphens
        .replace(/^-|-$/g, "") // Trim hyphens
        .slice(0, maxLength);
}
// =============================================================================
// ID GENERATION FUNCTIONS
// =============================================================================
/**
 * Generate a unique ID with optional prefix
 * @param prefix Optional prefix for the ID (e.g., 'user', 'session')
 * @returns Unique ID string
 */
export function generateId(prefix) {
    const id = nanoid();
    return prefix ? `${prefix}-${id}` : id;
}
/**
 * Generate a session ID with unified format
 *
 * Format: sess-<timestamp>-<random>
 * Example: sess-1733657123456-a1b2c3
 *
 * @returns SessionId branded type
 */
export function generateSessionId() {
    return makeSessionId(`${ID_PREFIX.SESSION}-${Date.now()}-${randomSuffix()}`);
}
/**
 * Generate a snapshot ID in the standard format
 * Format with description: snapshot-<slug>-<timestamp>-<random>
 * Format without: snapshot-<timestamp>-<random>
 * @param description Optional human-readable description
 * @returns SnapshotId branded type
 */
export function generateSnapshotId(description) {
    if (description && description.length > 0) {
        const slug = slugify(description);
        if (slug.length > 0) {
            return makeSnapshotId(`snapshot-${slug}-${Date.now()}-${nanoid(9)}`);
        }
    }
    return makeSnapshotId(`snapshot-${Date.now()}-${nanoid(9)}`);
}
/**
 * Generate an audit entry ID with unified format
 *
 * Format: audit-<timestamp>-<random>
 * Example: audit-1733657123456-d4e5f6
 *
 * @returns AuditId branded type
 */
export function generateAuditId() {
    return makeAuditId(`${ID_PREFIX.AUDIT}-${Date.now()}-${randomSuffix()}`);
}
/**
 * Generate a checkpoint ID with unified format
 *
 * Format: cp-<timestamp>-<random>
 * Example: cp-1733657123456-g7h8i9
 *
 * @returns Checkpoint ID string
 */
export function generateCheckpointId() {
    return `${ID_PREFIX.CHECKPOINT}-${Date.now()}-${randomSuffix()}`;
}
/**
 * Generate a random alphanumeric ID string
 *
 * @param length - Length of the ID (default: 6)
 * @returns Lowercase alphanumeric string
 */
export function randomId(length = 6) {
    return randomSuffix(length);
}
// =============================================================================
// ID PARSING FUNCTIONS
// =============================================================================
/**
 * Parse timestamp from a generated ID
 *
 * Handles all ID formats:
 * - sess-<timestamp>-<random>
 * - audit-<timestamp>-<random>
 * - cp-<timestamp>-<random>
 * - vreko-<timestamp>-<random>
 * - vreko-<slug>-<timestamp>-<random>
 * - snapshot-<timestamp>-<random> (legacy)
 * - snapshot-<slug>-<timestamp>-<random> (legacy)
 *
 * @param id - ID string to parse
 * @returns Timestamp in milliseconds, or null if invalid format
 */
export function parseIdTimestamp(id) {
    // Validate known prefix (includes legacy "snapshot" for backward compatibility)
    if (!id.match(/^(?:sess|vreko|snapshot|audit|cp)-/)) {
        return null;
    }
    // Match 13-digit timestamp before the final random suffix
    // Works for both `prefix-<timestamp>-<random>` and `prefix-<slug>-<timestamp>-<random>`
    const match = id.match(/-(\d{13})-[a-zA-Z0-9_-]+$/);
    if (!match) {
        return null;
    }
    const timestamp = Number.parseInt(match[1], 10);
    return Number.isNaN(timestamp) ? null : timestamp;
}
/**
 * Extract the prefix from a generated ID
 *
 * @param id - ID string to parse
 * @returns ID prefix or null if invalid format
 */
export function parseIdPrefix(id) {
    // Handle legacy "snapshot" prefix as "vreko"
    if (id.startsWith("snapshot-")) {
        return "vreko";
    }
    const match = id.match(/^(sess|vreko|audit|cp)-/);
    return match ? match[1] : null;
}
/**
 * Validate that an ID matches the expected format
 *
 * Handles formats:
 * - sess/audit/cp-<timestamp>-<6 random chars>
 * - vreko-<timestamp>-<9 random chars>
 * - vreko-<slug>-<timestamp>-<9 random chars>
 * - snapshot-* (legacy format, also valid)
 *
 * @param id - ID string to validate
 * @param expectedPrefix - Expected prefix (optional, validates any if not specified)
 * @returns True if valid, false otherwise
 */
export function isValidId(id, expectedPrefix) {
    // Snapshot IDs can have optional slug and use 9-char suffix
    // Also handle legacy "snapshot-" prefix
    const isSnapshotId = id.startsWith("vreko-") || id.startsWith("snapshot-");
    if (expectedPrefix === "vreko" || (!expectedPrefix && isSnapshotId)) {
        return /^(?:vreko|snapshot)-(?:[a-z0-9]+-)?(\d{13})-[a-zA-Z0-9_-]{9}$/.test(id);
    }
    // Non-snapshot IDs use 6-char suffix
    if (expectedPrefix) {
        const regex = new RegExp(`^${expectedPrefix}-\\d{13}-[a-z0-9]{6}$`);
        return regex.test(id);
    }
    return /^(?:sess|audit|cp)-\d{13}-[a-z0-9]{6}$/.test(id);
}
